import{c as t,Q as e,j as o,m as c}from"./chunks/framework.DK3sgdKX.js";const n=JSON.parse('{"title":"TH06 引擎机制覆盖清单","description":"","frontmatter":{},"headers":[],"relativePath":"TH06_API_COVERAGE.md","filePath":"TH06_API_COVERAGE.md","lastUpdated":1795193770000}'),r={name:"TH06_API_COVERAGE.md"};function E(a,d,T,A,L,s){return e(),o("div",null,[...d[0]||(d[0]=[c('<h1 id="th06-引擎机制覆盖清单" tabindex="-1">TH06 引擎机制覆盖清单 <a class="header-anchor" href="#th06-引擎机制覆盖清单" aria-label="Permalink to &quot;TH06 引擎机制覆盖清单&quot;">​</a></h1><p>本文对照东方红魔乡（TH06）的 ECL 机制，梳理哪些玩法可以直接使用 PySTG 现有公开 Python API 表达，哪些能力仍在缺口中。目标是验证引擎通用表达力，不引入原版 ECL/ANM 虚拟机，也不包含任何原作素材或版权资源。</p><p>机制参考自公开反编译源码 <a href="https://github.com/YomotsuHisami/th06" target="_blank" rel="noreferrer">YomotsuHisami/th06</a>。高级用法示例见 <code>game_content/examples/th06_*.py</code>，脚本 API 详见 <a href="./STAGE_SCRIPTING_GUIDE">弹幕脚本开发指南</a>。</p><h2 id="_1-按-ecl-指令范围对照" tabindex="-1">1. 按 ECL 指令范围对照 <a class="header-anchor" href="#_1-按-ecl-指令范围对照" aria-label="Permalink to &quot;1. 按 ECL 指令范围对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令范围</th><th>对应 PySTG 公开 API / 写法</th><th>说明与边界</th></tr></thead><tbody><tr><td><code>0–3</code></td><td>Python 控制流与 <code>await self.wait(n)</code></td><td><code>1</code>（<code>UNIMP</code>）为原版空槽</td></tr><tr><td><code>4–12</code></td><td>局部变量、定种 RNG、<code>actor.x</code> / <code>actor.y</code></td><td>2D 角色不维护独立 3D <code>z</code> 轴</td></tr><tr><td><code>13–26</code></td><td>Python / NumPy / Numba 运算</td><td>C 风格的整数截断与负余数需在内容脚本中显式处理</td></tr><tr><td><code>27–42</code></td><td><code>if</code> / <code>while</code>、普通函数、<code>spawn_task</code> / <code>parallel</code></td><td>不保留 ECL 栈帧地址，按协程结构重写</td></tr><tr><td><code>43–51</code></td><td><code>set_position</code>、<code>move_linear</code>、<code>move_velocity</code></td><td>坐标与速度使用世界归一化单位/秒</td></tr><tr><td><code>52–64</code></td><td><code>move_to(..., easing=...)</code></td><td>支持线性及二次/四次缓入缓出</td></tr><tr><td><code>65–66</code></td><td><code>set_movement_bounds</code> / <code>clear_movement_bounds</code></td><td><code>set_position</code> 与标准移动均遵守边界</td></tr><tr><td><code>67–75</code></td><td><code>fire_arc</code> / <code>fire_circle</code> / <code>create_bullets_batch</code></td><td>偏移环、随机角与多层弹用 NumPy 数组批量生成</td></tr><tr><td><code>76–81</code></td><td>角色 <code>Task</code> 循环与可取消句柄</td><td>不增加隐藏发射时钟，新弹次帧运动</td></tr><tr><td><code>82</code></td><td><code>set_bullet_behavior</code>、二维加速度、限次反弹/穿屏、批量变换</td><td>常用弹幕效果已覆盖，复杂组合由内容组装</td></tr><tr><td><code>83–84</code></td><td><code>clear_bullets_by_tag</code> / <code>bullets_by_tag_to_item</code> / <code>play_se</code></td><td>清场与自然到期语义分开</td></tr><tr><td><code>85–92</code></td><td><code>create_laser</code>、<code>configure_motion</code> / <code>configure_lifecycle</code>、<code>destroy</code></td><td>支持动态移动段与独立警告/碰撞窗口</td></tr><tr><td><code>93–94</code></td><td><code>BossPhase</code>、<code>SpellCard</code>、<code>bonus_rule</code>、<code>finish_rule</code>、<code>SpellResult</code></td><td>原作全部收符公式需由内容策略实现</td></tr><tr><td><code>95–96</code></td><td><code>spawn_enemy_class</code>、<code>add_enemy_script</code>、<code>kill</code> / <code>dispose</code></td><td><code>kill</code> 触发掉落，取消用 <code>dispose</code></td></tr><tr><td><code>97–100</code></td><td><code>play_animation</code>、<code>set_visual</code>、<code>attach_animation</code>、<code>ctx.play_animation</code></td><td>通用主/附属动画控制已具备，不含原作 ANM 数据</td></tr><tr><td><code>101–102</code></td><td><code>BossDef</code> / <code>run_boss</code> 与符卡宣言接口</td><td>宣言装饰特效可继续扩充</td></tr><tr><td><code>103–105</code></td><td><code>set_hitbox</code>、<code>set_interaction(collidable, damageable)</code></td><td>支持不可受伤但可触发 <code>on_hit</code> 的假身</td></tr><tr><td><code>106–108</code></td><td><code>play_se</code>、<code>on_death</code>（托管至存活 <code>StageContext</code>）</td><td>死亡后可继续异步发弹或放特效</td></tr><tr><td><code>109–110</code></td><td><code>on_hit</code>、<code>emit_event</code> / <code>wait_event</code>、取消或替换 <code>Task</code></td><td>按稀疏事件和结构化任务表达中断</td></tr><tr><td><code>111–116</code></td><td><code>hp</code>、<code>hp_threshold</code>、<code>wait_until</code>、<code>set_timer</code>、<code>timer_frames</code></td><td>支持 HP 阈值切卡与独立 Boss 计时</td></tr><tr><td><code>117</code></td><td><code>set_interaction(interactable=...)</code></td><td>独立控制是否参与命中与自机追踪</td></tr><tr><td><code>118–120</code></td><td><code>spawn_item</code> / <code>spawn_drop</code>、<code>emit_particles</code>、<code>set_visual</code></td><td>独立粒子池与视觉变换已接入</td></tr><tr><td><code>121–123</code></td><td>普通函数、批量数值公式、角色 Task</td><td>17 个特殊函数见第 2 节</td></tr><tr><td><code>124</code></td><td><code>set_item_collection_rule</code>、<code>GameStats</code> 回调</td><td>可配置 128P、得点、Extend 等规则</td></tr><tr><td><code>125</code></td><td><code>ctx.background</code>、<code>stop_time(&quot;background&quot;)</code></td><td>支持 3D 静态场景、雾效与独立背景暂停</td></tr><tr><td><code>126–130</code></td><td>Boss HUD 与动画替换接口</td><td>Boss 动态残机段数显示接口待细化</td></tr><tr><td><code>131</code></td><td><code>ctx.run_state.rank</code> / <code>adjust_rank</code> / <code>rank_value</code></td><td>跨关共享 Rank，支持稀疏事件增减</td></tr><tr><td><code>132–135</code></td><td><code>visible</code>、<code>set_timer</code>、<code>clear_all_lasers</code>、<code>finish_rule</code></td><td>支持耐久/超时分支结算</td></tr></tbody></table><h2 id="_2-17-个特殊函数对照" tabindex="-1">2. 17 个特殊函数对照 <a class="header-anchor" href="#_2-17-个特殊函数对照" aria-label="Permalink to &quot;2. 17 个特殊函数对照&quot;">​</a></h2><p>参考 <code>src/EnemyEclInstr.cpp</code>：</p><table tabindex="0"><thead><tr><th>函数</th><th>核心机制</th><th>PySTG 对应方案</th></tr></thead><tbody><tr><td><code>CirnoRainbowBallJank</code></td><td>停弹后施加每弹随机二维加速度，220 帧后清零</td><td>共享阶段 + NumPy <code>vector_accel</code></td></tr><tr><td><code>ShootAtRandomArea</code></td><td>每次随机发射原点</td><td><code>create_bullets_batch</code> 传 <code>(N, 2)</code> 位置数组</td></tr><tr><td><code>ShootStarPattern</code></td><td>星形边插值，保留初始玩家快照</td><td>NumPy 批量生成位置数组</td></tr><tr><td><code>PatchouliShottypeSetVars</code></td><td>按玩家机体/武器分支</td><td>读取 <code>ctx.player_shot</code> 与 <code>ctx.difficulty</code></td></tr><tr><td><code>Stage56Func4</code></td><td>世界时停 + 有限数量随机改向</td><td><code>ctx.stop_time()</code> + 批量筛选改向</td></tr><tr><td><code>Stage5Func5</code></td><td>九组位置矩阵发射</td><td>NumPy 位置/角度/速度数组一次批量发射</td></tr><tr><td><code>BatWingEffect</code></td><td>镜像双翼装饰粒子</td><td><code>emit_particles</code> + <code>ParticleEffect</code>（见 <code>th06_particles.py</code>）</td></tr><tr><td><code>Stage6Func7</code></td><td>两组八方向、三层、48 条交错激光</td><td><code>create_laser</code> + <code>configure_lifecycle</code>（见 <code>th06_controls.py</code>）</td></tr><tr><td><code>Stage6Func8</code></td><td>从大弹当前位置派生静止小弹</td><td><code>read_bullets(fields=(&quot;pos&quot;,))</code> + <code>create_bullets_batch</code></td></tr><tr><td><code>Stage6Func9</code></td><td>停弹按距 Boss 距离公式启动与加速</td><td><code>distance_acceleration</code> + <code>transform_bullets</code>（见 <code>th06_patterns.py</code>）</td></tr><tr><td><code>Stage6Func11</code></td><td>停弹后施加随机加速度，120 帧后清除</td><td><code>snapshot.select</code> + <code>vector_accel</code></td></tr><tr><td><code>HandleBatTransformation</code></td><td>Bomb 期间敌人不可交互，结束后延迟 60 帧恢复</td><td>观察 <code>player.is_bombing</code> + <code>set_interaction</code>（见 <code>th06_controls.py</code>）</td></tr><tr><td><code>Stage4Func12</code></td><td>沿激光方向距敌 64px 处发弹</td><td>读取 <code>laser.angle</code> 与角色位置批量发射</td></tr><tr><td><code>StageXFunc13</code></td><td>每 6 帧从圆周点发射</td><td>普通协程循环 + 局部角度</td></tr><tr><td><code>StageXFunc14</code></td><td>沿移动激光当前段每 48px 发弹</td><td><code>laser.sample_points(step)</code> + 批量发射</td></tr><tr><td><code>StageXFunc15</code></td><td>严格邻域、按槽序首次匹配激活改向</td><td><code>neighbor_activation</code>（见 <code>th06_patterns.py</code>）</td></tr><tr><td><code>FlandreFinalContextUpdate</code></td><td>按 HP 与计时动态调整速度、间隔和随机域</td><td>读取 <code>boss.hp</code> 与 <code>spell.timer_frames</code> 批量发射</td></tr></tbody></table><h2 id="_3-主要剩余缺口" tabindex="-1">3. 主要剩余缺口 <a class="header-anchor" href="#_3-主要剩余缺口" aria-label="Permalink to &quot;3. 主要剩余缺口&quot;">​</a></h2><ul><li><strong>内容与策略层面</strong>：原作六关 + Extra 的具体关卡脚本、128P/得点/Extend/Rank 精确数值表、完整 Deathbomb 策略均属于游戏内容层工作，引擎仅提供通用钩子。</li><li><strong>视觉与演出层面</strong>：原作 ANM 精细时序、三维深度排序、Boss 宣言/时停滤镜与 HUD 特殊样式尚未完全覆盖。</li><li><strong>GUI 编辑器覆盖</strong>：上述批量数组规则、自定义受击/结算规则和粒子/动画高级接口目前面向手写 Python 脚本（或编辑器内 <code>RawPython</code>），尚未全部做成拖拽节点。</li></ul><h2 id="附录-136-项-ecl-指令编号索引" tabindex="-1">附录：136 项 ECL 指令编号索引 <a class="header-anchor" href="#附录-136-项-ecl-指令编号索引" aria-label="Permalink to &quot;附录：136 项 ECL 指令编号索引&quot;">​</a></h2><p>以下列出原版枚举名称（省略 <code>ECL_OPCODE_</code> 前缀），便于对照第 1 节：</p><table tabindex="0"><thead><tr><th>编号</th><th>名称</th><th>编号</th><th>名称</th><th>编号</th><th>名称</th></tr></thead><tbody><tr><td>0</td><td><code>NOP</code></td><td>46</td><td><code>MOVEANGULARVELOCITY</code></td><td>92</td><td><code>LASERCANCEL</code></td></tr><tr><td>1</td><td><code>UNIMP</code></td><td>47</td><td><code>MOVESPEED</code></td><td>93</td><td><code>SPELLCARDSTART</code></td></tr><tr><td>2</td><td><code>JUMP</code></td><td>48</td><td><code>MOVEACCELERATION</code></td><td>94</td><td><code>SPELLCARDEND</code></td></tr><tr><td>3</td><td><code>JUMPDEC</code></td><td>49</td><td><code>MOVERAND</code></td><td>95</td><td><code>ENEMYCREATE</code></td></tr><tr><td>4</td><td><code>SETINT</code></td><td>50</td><td><code>MOVERANDINBOUND</code></td><td>96</td><td><code>ENEMYKILLALL</code></td></tr><tr><td>5</td><td><code>SETFLOAT</code></td><td>51</td><td><code>MOVEATPLAYER</code></td><td>97</td><td><code>ANMSETMAIN</code></td></tr><tr><td>6</td><td><code>SETINTRAND</code></td><td>52</td><td><code>MOVEDIRTIMEDECELERATE</code></td><td>98</td><td><code>ANMSETPOSES</code></td></tr><tr><td>7</td><td><code>SETINTRANDMIN</code></td><td>53</td><td><code>MOVEDIRTIMEDECELERATEFAST</code></td><td>99</td><td><code>ANMSETSLOT</code></td></tr><tr><td>8</td><td><code>SETFLOATRAND</code></td><td>54</td><td><code>MOVEDIRTIMEACCELERATE</code></td><td>100</td><td><code>ANMSETDEATH</code></td></tr><tr><td>9</td><td><code>SETFLOATRANDMIN</code></td><td>55</td><td><code>MOVEDIRTIMEACCELERATEFAST</code></td><td>101</td><td><code>BOSSSET</code></td></tr><tr><td>10</td><td><code>SETVARSELFX</code></td><td>56</td><td><code>MOVEPOSITIONTIMELINEAR</code></td><td>102</td><td><code>SPELLCARDEFFECT</code></td></tr><tr><td>11</td><td><code>SETVARSELFY</code></td><td>57</td><td><code>MOVEPOSITIONTIMEDECELERATE</code></td><td>103</td><td><code>ENEMYSETHITBOX</code></td></tr><tr><td>12</td><td><code>SETVARSELFZ</code></td><td>58</td><td><code>MOVEPOSITIONTIMEDECELERATEFAST</code></td><td>104</td><td><code>ENEMYFLAGCOLLISION</code></td></tr><tr><td>13</td><td><code>MATHINTADD</code></td><td>59</td><td><code>MOVEPOSITIONTIMEACCELERATE</code></td><td>105</td><td><code>ENEMYFLAGCANTAKEDAMAGE</code></td></tr><tr><td>14</td><td><code>MATHINTSUB</code></td><td>60</td><td><code>MOVEPOSITIONTIMEACCELERATEFAST</code></td><td>106</td><td><code>EFFECTSOUND</code></td></tr><tr><td>15</td><td><code>MATHINTMUL</code></td><td>61</td><td><code>MOVETIMEDECELERATE</code></td><td>107</td><td><code>ENEMYFLAGDEATH</code></td></tr><tr><td>16</td><td><code>MATHINTDIV</code></td><td>62</td><td><code>MOVETIMEDECELERATEFAST</code></td><td>108</td><td><code>DEATHCALLBACKSUB</code></td></tr><tr><td>17</td><td><code>MATHINTMOD</code></td><td>63</td><td><code>MOVETIMEACCELERATE</code></td><td>109</td><td><code>ENEMYINTERRUPTSET</code></td></tr><tr><td>18</td><td><code>MATHINC</code></td><td>64</td><td><code>MOVETIMEACCELERATEFAST</code></td><td>110</td><td><code>ENEMYINTERRUPT</code></td></tr><tr><td>19</td><td><code>MATHDEC</code></td><td>65</td><td><code>MOVEBOUNDSSET</code></td><td>111</td><td><code>ENEMYLIFESET</code></td></tr><tr><td>20</td><td><code>MATHFLOATADD</code></td><td>66</td><td><code>MOVEBOUNDSDISABLE</code></td><td>112</td><td><code>BOSSTIMERSET</code></td></tr><tr><td>21</td><td><code>MATHFLOATSUB</code></td><td>67</td><td><code>BULLETFANAIMED</code></td><td>113</td><td><code>LIFECALLBACKTHRESHOLD</code></td></tr><tr><td>22</td><td><code>MATHFLOATMUL</code></td><td>68</td><td><code>BULLETFAN</code></td><td>114</td><td><code>LIFECALLBACKSUB</code></td></tr><tr><td>23</td><td><code>MATHFLOATDIV</code></td><td>69</td><td><code>BULLETCIRCLEAIMED</code></td><td>115</td><td><code>TIMERCALLBACKTHRESHOLD</code></td></tr><tr><td>24</td><td><code>MATHFLOATMOD</code></td><td>70</td><td><code>BULLETCIRCLE</code></td><td>116</td><td><code>TIMERCALLBACKSUB</code></td></tr><tr><td>25</td><td><code>MATHATAN2</code></td><td>71</td><td><code>BULLETOFFSETCIRCLEAIMED</code></td><td>117</td><td><code>ENEMYFLAGINTERACTABLE</code></td></tr><tr><td>26</td><td><code>MATHNORMANGLE</code></td><td>72</td><td><code>BULLETOFFSETCIRCLE</code></td><td>118</td><td><code>EFFECTPARTICLE</code></td></tr><tr><td>27</td><td><code>CMPINT</code></td><td>73</td><td><code>BULLETRANDOMANGLE</code></td><td>119</td><td><code>DROPITEMS</code></td></tr><tr><td>28</td><td><code>CMPFLOAT</code></td><td>74</td><td><code>BULLETRANDOMSPEED</code></td><td>120</td><td><code>ANMFLAGROTATION</code></td></tr><tr><td>29</td><td><code>JUMPLSS</code></td><td>75</td><td><code>BULLETRANDOM</code></td><td>121</td><td><code>EXINSCALL</code></td></tr><tr><td>30</td><td><code>JUMPLEQ</code></td><td>76</td><td><code>SHOOTINTERVAL</code></td><td>122</td><td><code>EXINSREPEAT</code></td></tr><tr><td>31</td><td><code>JUMPEQU</code></td><td>77</td><td><code>SHOOTINTERVALDELAYED</code></td><td>123</td><td><code>TIMESET</code></td></tr><tr><td>32</td><td><code>JUMPGRE</code></td><td>78</td><td><code>SHOOTDISABLED</code></td><td>124</td><td><code>DROPITEMID</code></td></tr><tr><td>33</td><td><code>JUMPGEQ</code></td><td>79</td><td><code>SHOOTENABLED</code></td><td>125</td><td><code>STDUNPAUSE</code></td></tr><tr><td>34</td><td><code>JUMPNEQ</code></td><td>80</td><td><code>SHOOTNOW</code></td><td>126</td><td><code>BOSSSETLIFECOUNT</code></td></tr><tr><td>35</td><td><code>CALL</code></td><td>81</td><td><code>SHOOTOFFSET</code></td><td>127</td><td><code>DEBUGWATCH</code></td></tr><tr><td>36</td><td><code>RET</code></td><td>82</td><td><code>BULLETEFFECTS</code></td><td>128</td><td><code>ANMINTERRUPTMAIN</code></td></tr><tr><td>37</td><td><code>CALLLSS</code></td><td>83</td><td><code>BULLETCANCEL</code></td><td>129</td><td><code>ANMINTERRUPTSLOT</code></td></tr><tr><td>38</td><td><code>CALLLEQ</code></td><td>84</td><td><code>BULLETSOUND</code></td><td>130</td><td><code>ENEMYFLAGDISABLECALLSTACK</code></td></tr><tr><td>39</td><td><code>CALLEQU</code></td><td>85</td><td><code>LASERCREATE</code></td><td>131</td><td><code>BULLETRANKINFLUENCE</code></td></tr><tr><td>40</td><td><code>CALLGRE</code></td><td>86</td><td><code>LASERCREATEAIMED</code></td><td>132</td><td><code>ENEMYFLAGINVISIBLE</code></td></tr><tr><td>41</td><td><code>CALLGEQ</code></td><td>87</td><td><code>LASERINDEX</code></td><td>133</td><td><code>BOSSTIMERCLEAR</code></td></tr><tr><td>42</td><td><code>CALLNEQ</code></td><td>88</td><td><code>LASERROTATE</code></td><td>134</td><td><code>LASERCLEARALL</code></td></tr><tr><td>43</td><td><code>MOVEPOSITION</code></td><td>89</td><td><code>LASERROTATEFROMPLAYER</code></td><td>135</td><td><code>SPELLCARDFLAGTIMEOUT</code></td></tr><tr><td>44</td><td><code>MOVEAXISVELOCITY</code></td><td>90</td><td><code>LASEROFFSET</code></td><td></td><td></td></tr><tr><td>45</td><td><code>MOVEVELOCITY</code></td><td>91</td><td><code>LASERTEST</code></td><td></td><td></td></tr></tbody></table>',13)])])}const i=t(r,[["render",E]]);export{n as __pageData,i as default};
